-- 预算分层与合同付款节点：区分批准预算、到账、在途申请、已入账支出和实际付款。
BEGIN;

CREATE TABLE IF NOT EXISTS "项目经费台账" (
    "编号" bigint GENERATED BY DEFAULT AS IDENTITY,
    "流程模板编号" integer NOT NULL,
    "项目编号" integer NOT NULL,
    "业务类型" varchar(20) NOT NULL,
    "金额" numeric(18,2) NOT NULL,
    "状态" varchar(10) NOT NULL DEFAULT '待审核',
    "业务编号" varchar(100),
    "交易日期" date,
    "付款日期" date,
    "收款方" varchar(200),
    "凭证路径" varchar(1000),
    "备注" varchar(1000),
    "建立人编号" integer NOT NULL,
    "建立时间" timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "更新时间" timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT "pk_项目经费台账" PRIMARY KEY ("编号"),
    CONSTRAINT "ck_项目经费台账_业务类型" CHECK ("业务类型" IN ('付款申请','实际付款','其他收入','冲销')),
    CONSTRAINT "ck_项目经费台账_状态" CHECK ("状态" IN ('待审核','已审批','已付款','已驳回','已冲销')),
    CONSTRAINT "ck_项目经费台账_金额" CHECK ("金额" > 0),
    CONSTRAINT "ck_项目经费台账_付款日期" CHECK ("业务类型" <> '实际付款' OR "付款日期" IS NOT NULL)
);

CREATE INDEX IF NOT EXISTS "ix_项目经费台账_项目"
    ON "项目经费台账" ("流程模板编号", "项目编号", "业务类型", "状态", "交易日期" DESC);
CREATE UNIQUE INDEX IF NOT EXISTS "uq_项目经费台账_业务编号"
    ON "项目经费台账" ("流程模板编号", "项目编号", "业务类型", "业务编号")
    WHERE "业务编号" IS NOT NULL;

CREATE TABLE IF NOT EXISTS "项目合同付款节点" (
    "编号" bigint GENERATED BY DEFAULT AS IDENTITY,
    "流程模板编号" integer NOT NULL,
    "项目编号" integer NOT NULL,
    "节点序号" integer NOT NULL,
    "节点名称" varchar(200) NOT NULL,
    "约定金额" numeric(18,2) NOT NULL,
    "到期日期" date,
    "状态" varchar(10) NOT NULL DEFAULT '计划',
    "已付款金额" numeric(18,2) NOT NULL DEFAULT 0,
    "合同编号" varchar(100),
    "备注" varchar(1000),
    "建立人编号" integer NOT NULL,
    "建立时间" timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "更新时间" timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT "pk_项目合同付款节点" PRIMARY KEY ("编号"),
    CONSTRAINT "uq_项目合同付款节点_序号" UNIQUE ("流程模板编号", "项目编号", "节点序号"),
    CONSTRAINT "ck_项目合同付款节点_序号" CHECK ("节点序号" > 0),
    CONSTRAINT "ck_项目合同付款节点_约定金额" CHECK ("约定金额" > 0),
    CONSTRAINT "ck_项目合同付款节点_已付款金额" CHECK ("已付款金额" >= 0 AND "已付款金额" <= "约定金额"),
    CONSTRAINT "ck_项目合同付款节点_状态" CHECK ("状态" IN ('计划','待申请','申请中','部分付款','已付款','逾期','取消'))
);

CREATE INDEX IF NOT EXISTS "ix_项目合同付款节点_项目"
    ON "项目合同付款节点" ("流程模板编号", "项目编号", "到期日期", "节点序号");

CREATE OR REPLACE FUNCTION "tfn_项目经费分层"(
    p_flow_template_id integer DEFAULT NULL,
    p_project_id integer DEFAULT NULL
)
RETURNS TABLE (
    "流程模板编号" integer,
    "项目编号" integer,
    "批准预算" numeric,
    "待审核到账" numeric,
    "已入账到账" numeric,
    "在途付款申请" numeric,
    "待审核报销" numeric,
    "已入账支出" numeric,
    "实际付款" numeric,
    "可用预算余额" numeric,
    "合同节点数" bigint,
    "待付款节点数" bigint,
    "异常类型" text,
    "异常说明" text,
    "统计口径" text
)
LANGUAGE sql STABLE AS $$
WITH budgets AS (
    SELECT b."流程模板编号", b."项目编号", SUM(COALESCE(b."批准经费",0) + COALESCE(b."配套经费",0))::numeric AS amount
      FROM "项目经费预算" b
     WHERE b."流程模板编号" = COALESCE(p_flow_template_id,b."流程模板编号")
       AND b."项目编号" = COALESCE(p_project_id,b."项目编号")
     GROUP BY b."流程模板编号", b."项目编号"
), arrivals AS (
    SELECT a."流程模板编号", a."项目编号",
           SUM(CASE WHEN f."状态" = 1 THEN COALESCE(a."到账金额",0) ELSE 0 END)::numeric AS posted,
           SUM(CASE WHEN COALESCE(f."状态",0) = 0 THEN COALESCE(a."到账金额",0) ELSE 0 END)::numeric AS pending
      FROM "项目经费到账" a
      LEFT JOIN LATERAL (
          SELECT f1."状态" FROM "流程" f1
           WHERE f1."流程模板编号" = 500 AND f1."项目编号" = a."编号"
           ORDER BY f1."编号" DESC LIMIT 1
      ) f ON TRUE
     WHERE a."流程模板编号" = COALESCE(p_flow_template_id,a."流程模板编号")
       AND a."项目编号" = COALESCE(p_project_id,a."项目编号")
       AND COALESCE(f."状态",0) IN (0,1)
     GROUP BY a."流程模板编号", a."项目编号"
), expenses AS (
    SELECT r."流程模板编号", r."项目编号",
           SUM(CASE WHEN f."状态" = 1 THEN COALESCE(r."报销金额",0) ELSE 0 END)::numeric AS posted,
           SUM(CASE WHEN COALESCE(f."状态",0) = 0 THEN COALESCE(r."报销金额",0) ELSE 0 END)::numeric AS pending
      FROM "报销" r
      LEFT JOIN LATERAL (
          SELECT f1."状态" FROM "流程" f1
           WHERE f1."流程模板编号" = 600 AND f1."项目编号" = r."编号"
           ORDER BY f1."编号" DESC LIMIT 1
      ) f ON TRUE
     WHERE r."流程模板编号" = COALESCE(p_flow_template_id,r."流程模板编号")
       AND r."项目编号" = COALESCE(p_project_id,r."项目编号")
       AND COALESCE(f."状态",0) IN (0,1)
     GROUP BY r."流程模板编号", r."项目编号"
), ledger AS (
    SELECT l."流程模板编号", l."项目编号",
           SUM(CASE WHEN l."业务类型" = '付款申请' AND l."状态" IN ('待审核','已审批') THEN l."金额" ELSE 0 END)::numeric AS in_transit,
           SUM(CASE WHEN l."业务类型" = '实际付款' AND l."状态" = '已付款' THEN l."金额" ELSE 0 END)::numeric AS paid
      FROM "项目经费台账" l
     WHERE l."流程模板编号" = COALESCE(p_flow_template_id,l."流程模板编号")
       AND l."项目编号" = COALESCE(p_project_id,l."项目编号")
     GROUP BY l."流程模板编号", l."项目编号"
), milestones AS (
    SELECT m."流程模板编号", m."项目编号", count(*)::bigint AS total,
           count(*) FILTER (WHERE m."状态" NOT IN ('已付款','取消'))::bigint AS outstanding
      FROM "项目合同付款节点" m
     WHERE m."流程模板编号" = COALESCE(p_flow_template_id,m."流程模板编号")
       AND m."项目编号" = COALESCE(p_project_id,m."项目编号")
     GROUP BY m."流程模板编号", m."项目编号"
), keys AS (
    SELECT "流程模板编号","项目编号" FROM budgets
    UNION SELECT "流程模板编号","项目编号" FROM arrivals
    UNION SELECT "流程模板编号","项目编号" FROM expenses
    UNION SELECT "流程模板编号","项目编号" FROM ledger
    UNION SELECT "流程模板编号","项目编号" FROM milestones
    UNION SELECT p_flow_template_id,p_project_id WHERE p_flow_template_id IS NOT NULL AND p_project_id IS NOT NULL
), totals AS (
    SELECT k."流程模板编号", k."项目编号",
           COALESCE(b.amount,0)::numeric AS budget,
           COALESCE(a.pending,0)::numeric AS arrival_pending,
           COALESCE(a.posted,0)::numeric AS arrival_posted,
           COALESCE(l.in_transit,0)::numeric AS in_transit,
           COALESCE(e.pending,0)::numeric AS expense_pending,
           COALESCE(e.posted,0)::numeric AS expense_posted,
           COALESCE(l.paid,0)::numeric AS paid,
           COALESCE(m.total,0)::bigint AS milestone_count,
           COALESCE(m.outstanding,0)::bigint AS outstanding_count
      FROM keys k
      LEFT JOIN budgets b USING ("流程模板编号","项目编号")
      LEFT JOIN arrivals a USING ("流程模板编号","项目编号")
      LEFT JOIN expenses e USING ("流程模板编号","项目编号")
      LEFT JOIN ledger l USING ("流程模板编号","项目编号")
      LEFT JOIN milestones m USING ("流程模板编号","项目编号")
)
SELECT t."流程模板编号", t."项目编号", t.budget, t.arrival_pending, t.arrival_posted,
       t.in_transit, t.expense_pending, t.expense_posted, t.paid,
       (t.budget - t.expense_posted - t.paid)::numeric,
       t.milestone_count, t.outstanding_count,
       concat_ws('；',
           CASE WHEN t.expense_posted > t.budget THEN '已入账支出超批准预算' END,
           CASE WHEN t.arrival_posted > t.budget THEN '已入账到账超批准预算' END,
           CASE WHEN t.in_transit > (t.budget - t.expense_posted - t.paid) AND t.budget > 0 THEN '在途付款申请超过可用余额' END,
           CASE WHEN t.outstanding_count > 0 AND EXISTS (SELECT 1 FROM "项目合同付款节点" m WHERE m."流程模板编号"=t."流程模板编号" AND m."项目编号"=t."项目编号" AND m."到期日期" < CURRENT_DATE AND m."状态" NOT IN ('已付款','取消')) THEN '合同付款节点逾期' END
       ),
       concat_ws('；',
           CASE WHEN t.expense_posted > t.budget THEN '已审核报销和实际付款合计超过批准预算' END,
           CASE WHEN t.arrival_posted > t.budget THEN '已审核到账金额超过批准预算' END,
           CASE WHEN t.in_transit > (t.budget - t.expense_posted - t.paid) AND t.budget > 0 THEN '在途付款申请占用后预计超出可用预算' END,
           CASE WHEN t.outstanding_count > 0 AND EXISTS (SELECT 1 FROM "项目合同付款节点" m WHERE m."流程模板编号"=t."流程模板编号" AND m."项目编号"=t."项目编号" AND m."到期日期" < CURRENT_DATE AND m."状态" NOT IN ('已付款','取消')) THEN '存在已到期但未付款的合同节点' END
       ),
       '批准预算=预算表批准经费+配套经费；到账和报销按对应流程审批状态区分待审核与已入账；实际付款仅统计台账中状态为已付款的记录。'
  FROM totals t
 ORDER BY t."流程模板编号", t."项目编号";
$$;

UPDATE "系统迁移版本"
   SET "版本" = 46,
       "脚本" = '001-046',
       "检查摘要" = '增加预算分层台账、实际付款和合同付款节点'
 WHERE "编号" = 1;

COMMIT;
